import pandas as pd, numpy as np, warnings, io
warnings.filterwarnings('ignore')
from pymatgen.core import Structure, Element
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from pymatgen.analysis.local_env import CrystalNN
from sklearn.model_selection import KFold, cross_val_predict
from sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor, HistGradientBoostingRegressor, AdaBoostRegressor, BaggingRegressor
from sklearn.neighbors import KNeighborsRegressor
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler, RobustScaler
from sklearn.linear_model import Ridge, ElasticNet
from sklearn.compose import TransformedTargetRegressor
from sklearn.metrics import mean_absolute_error,r2_score

tr=pd.read_csv('nlo_shg_eg_train.csv'); po=pd.read_csv('nlo_pool.csv')
els=sorted({e.symbol for s in list(tr.formula)+list(po.formula) for e in __import__('pymatgen').core.Composition(s).elements})
props=['Z','X','atomic_mass','atomic_radius','average_ionic_radius','mendeleev_no','electron_affinity','group','row','is_metal','is_metalloid','is_rare_earth_metal']
cache={}
def struct(s):
 return Structure.from_str(s,fmt='poscar')

def feats(row):
 st=struct(row.poscar); comp=st.composition; sg=SpacegroupAnalyzer(st)
 try: sp=sg.get_space_group_number(); sym=sg.get_crystal_system()
 except: sp=0;sym='unknown'
 try: cent=int(sg.is_laue())
 except: cent=-1
 d={}
 fr=comp.fractional_composition
 for e in els:d['f_'+e]=fr.get_atomic_fraction(e)
 for p in props:
  vals=[getattr(e,p) for e in comp.elements]
  try: d['mean_'+p]=comp.get_property(p)
  except Exception:
   try: d['mean_'+p]=sum(getattr(e,p)*comp.get_atomic_fraction(e) for e in comp.elements)
   except: d['mean_'+p]=0
  try:d['range_'+p]=max(vals)-min(vals)
  except:d['range_'+p]=0
 l=st.lattice
 d.update(n_sites=len(st),vol=st.volume,density=st.density,vpa=st.volume/len(st),a=l.a,b=l.b,c=l.c,alpha=l.alpha,beta=l.beta,gamma=l.gamma,sg=sp,cent=cent)
 # composition ionic character, anion fractions
 for a in ['S','Se','Te','Cl','Br','I','O','N','P','As','Sb']:
  d['anion_'+a]=fr.get_atomic_fraction(a)
 return d

Xtr=pd.DataFrame([feats(r) for _,r in tr.iterrows()]).fillna(0)
Xpo=pd.DataFrame([feats(r) for _,r in po.iterrows()]).fillna(0)
Xpo=Xpo.reindex(columns=Xtr.columns,fill_value=0)
y1=np.log10(tr.shg); y2=tr.band_gap
models={
'rf':RandomForestRegressor(500,random_state=1,min_samples_leaf=1,max_features=.7,n_jobs=-1),
'et':ExtraTreesRegressor(800,random_state=2,min_samples_leaf=1,max_features=.8,n_jobs=-1),
'gbr':GradientBoostingRegressor(n_estimators=500,learning_rate=.03,max_depth=3,random_state=3,subsample=.8),
'hgb':HistGradientBoostingRegressor(max_iter=400,learning_rate=.04,max_leaf_nodes=15,l2_regularization=.1,random_state=4),
'knn':make_pipeline(StandardScaler(),KNeighborsRegressor(7,weights='distance')),
'ridge':make_pipeline(RobustScaler(),Ridge(100)),
}
print('features',Xtr.shape)
for target,name in [(y1,'logshg'),(y2,'gap')]:
 print('\n',name)
 oof={}
 for mn,m in models.items():
  try:
   p=cross_val_predict(m,Xtr,target,cv=KFold(10,shuffle=True,random_state=42),n_jobs=-1)
   print(mn,'MAE',mean_absolute_error(target,p),'R2',r2_score(target,p)); oof[mn]=p
  except Exception as e: print(mn,e)
 z=np.mean([oof[k] for k in ['rf','et','gbr','hgb','knn'] if k in oof],axis=0)
 print('ensemble MAE',mean_absolute_error(target,z),'R2',r2_score(target,z))
PY

