import pandas as pd,numpy as np
p=pd.read_csv('preds.csv'); p=p.set_index('candidate_id')
sets=[['c073','c030','c026','c057','c053'],['c073','c030','c026','c057','c084'],['c073','c055','c028','c084','c083']]
def hv(v):
 pts=sorted(v,key=lambda z:-z[0]); a=0;m=0
 for x,y in pts:
  if y>m:a+=x*(y-m);m=y
 return a
for s in sets:
 for typ in ['pred_shg','pred_shglin']:
  x=p.loc[s,typ].values/p[typ].max(); y=p.loc[s,'pred_gap'].values/p.pred_gap.max(); full=hv(zip(x,y)); losses=[]
  for i,z in enumerate(s): losses.append((z,full-hv(zip(np.delete(x,i),np.delete(y,i)))))
  print(s,typ,full,sorted(losses,key=lambda q:-q[1]))
